package com.sap.ec.core.exceptions

import com.sap.ec.core.networking.model.Response

sealed class SdkException(message: String) : RuntimeException(message) {
    class InvalidApplicationCodeException(message: String): SdkException(message)
    class SdkAlreadyEnabledException(message: String): SdkException(message)
    class SdkAlreadyDisabledException(message: String): SdkException(message)
    class SdkDisabledException(message: String): SdkException(message)
    class RetryLimitReachedException(message: String, val response: Response) : SdkException(message)
    class PreconditionFailedException(message: String): SdkException(message)
    class MissingApplicationCodeException(message: String = "Application code is missing!"): SdkException(message)
    class FailedRequestException(val response: Response) : SdkException("request: ${response.originalRequest.url}, responseBody: ${response.bodyAsText}")
    class NetworkIOException(message: String): SdkException(message)
    class CoroutineException(message: String): SdkException(message)
    class DecryptionFailedException(message: String): SdkException(message)
    class ServiceWorkerUnavailableException(message: String): SdkException(message)
    class PushManagerUnavailableException(message: String): SdkException(message)
    class MissingEventUrlException(message: String = "Event URL is missing!"): SdkException(message)
    class ContactTokenNotFoundException(message: String): SdkException(message)
    class RecommendationApiNotReadyException(message: String = "Recommendation API not ready!"): SdkException(message)
    class MissingRecommendationConfigurationException(message: String = "Missing recommendation configuration!"): SdkException(message)
    class InvalidRecommendationConfigurationException(message: String = "There's a problem with your recommendation configuration!"): SdkException(message)
    class RecommendationRequestFailedException(message: String = "Recommendation Request Failed!"): SdkException(message)
}
